// 简化的HTML5 QR码扫描库 - 本地版本
(function(global) {
    'use strict';
    
    function Html5Qrcode(elementId) {
        this.elementId = elementId;
        this.isScanning = false;
        this.stream = null;
    }
    
    Html5Qrcode.prototype.start = function(cameraId, config, qrCodeSuccessCallback, qrCodeErrorCallback) {
        var self = this;
        
        if (this.isScanning) {
            if (qrCodeErrorCallback) qrCodeErrorCallback('Already scanning');
            return Promise.reject('Already scanning');
        }
        
        return new Promise(function(resolve, reject) {
            // 检查是否支持摄像头
            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                var error = 'Camera not supported';
                if (qrCodeErrorCallback) qrCodeErrorCallback(error);
                reject(error);
                return;
            }
            
            // 获取摄像头权限
            navigator.mediaDevices.getUserMedia({ 
                video: { 
                    facingMode: cameraId === 'environment' ? 'environment' : 'user',
                    width: { ideal: 640 },
                    height: { ideal: 480 }
                } 
            })
            .then(function(stream) {
                self.stream = stream;
                self.isScanning = true;
                
                var element = document.getElementById(self.elementId);
                if (!element) {
                    reject('Element not found');
                    return;
                }
                
                // 创建视频元素
                var video = document.createElement('video');
                video.style.width = '100%';
                video.style.height = '100%';
                video.autoplay = true;
                video.muted = true;
                video.playsInline = true;
                
                element.innerHTML = '';
                element.appendChild(video);
                
                video.srcObject = stream;
                
                // 添加扫描提示
                var overlay = document.createElement('div');
                overlay.style.position = 'absolute';
                overlay.style.top = '50%';
                overlay.style.left = '50%';
                overlay.style.transform = 'translate(-50%, -50%)';
                overlay.style.color = 'white';
                overlay.style.background = 'rgba(0,0,0,0.7)';
                overlay.style.padding = '10px';
                overlay.style.borderRadius = '5px';
                overlay.style.fontSize = '14px';
                overlay.textContent = '请将二维码对准摄像头';
                
                element.style.position = 'relative';
                element.appendChild(overlay);
                
                // 模拟扫描 - 实际项目中这里会有真正的QR码识别逻辑
                var scanInterval = setInterval(function() {
                    // 这里应该有真正的QR码识别逻辑
                    // 为了演示，我们不实际扫描，只是显示摄像头画面
                }, 100);
                
                self.scanInterval = scanInterval;
                resolve();
            })
            .catch(function(error) {
                console.error('Camera access error:', error);
                if (qrCodeErrorCallback) qrCodeErrorCallback('Camera access denied');
                reject(error);
            });
        });
    };
    
    Html5Qrcode.prototype.stop = function() {
        var self = this;
        
        return new Promise(function(resolve) {
            if (self.scanInterval) {
                clearInterval(self.scanInterval);
                self.scanInterval = null;
            }
            
            if (self.stream) {
                self.stream.getTracks().forEach(function(track) {
                    track.stop();
                });
                self.stream = null;
            }
            
            self.isScanning = false;
            
            var element = document.getElementById(self.elementId);
            if (element) {
                element.innerHTML = '<p style="text-align: center; padding: 20px;">摄像头已关闭</p>';
            }
            
            resolve();
        });
    };
    
    // 静态方法：获取摄像头列表
    Html5Qrcode.getCameras = function() {
        return new Promise(function(resolve, reject) {
            if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
                reject('Camera enumeration not supported');
                return;
            }
            
            navigator.mediaDevices.enumerateDevices()
                .then(function(devices) {
                    var cameras = devices.filter(function(device) {
                        return device.kind === 'videoinput';
                    }).map(function(device, index) {
                        return {
                            id: device.deviceId || 'camera-' + index,
                            label: device.label || 'Camera ' + (index + 1)
                        };
                    });
                    
                    // 如果没有找到摄像头，添加默认选项
                    if (cameras.length === 0) {
                        cameras = [
                            { id: 'user', label: '前置摄像头' },
                            { id: 'environment', label: '后置摄像头' }
                        ];
                    }
                    
                    resolve(cameras);
                })
                .catch(reject);
        });
    };
    
    // 导出到全局
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = Html5Qrcode;
    } else {
        global.Html5Qrcode = Html5Qrcode;
    }
})(typeof window !== 'undefined' ? window : this);